import React, { useEffect, useRef, memo } from 'react';

// ── Symbol mapping: our coin symbols → TradingView BINANCE pairs ───────────
const TV_SYMBOL_MAP = {
  BTC:   'BINANCE:BTCUSDT',
  ETH:   'BINANCE:ETHUSDT',
  SOL:   'BINANCE:SOLUSDT',
  BNB:   'BINANCE:BNBUSDT',
  XRP:   'BINANCE:XRPUSDT',
  DOGE:  'BINANCE:DOGEUSDT',
  ADA:   'BINANCE:ADAUSDT',
  AVAX:  'BINANCE:AVAXUSDT',
  DOT:   'BINANCE:DOTUSDT',
  POL:   'BINANCE:MATICUSDT',
  MATIC: 'BINANCE:MATICUSDT',
  LINK:  'BINANCE:LINKUSDT',
  UNI:   'BINANCE:UNIUSDT',
  ATOM:  'BINANCE:ATOMUSDT',
  LTC:   'BINANCE:LTCUSDT',
  NEAR:  'BINANCE:NEARUSDT',
  APT:   'BINANCE:APTUSDT',
  ARB:   'BINANCE:ARBUSDT',
  OP:    'BINANCE:OPUSDT',
  TON:   'BINANCE:TONUSDT',
  SHIB:  'BINANCE:SHIBUSDT',
  IMX:   'BINANCE:IMXUSDT',
  BLUR:  'BINANCE:BLURUSDT',
  SEI:   'BINANCE:SEIUSDT',
  SUI:   'BINANCE:SUIUSDT',
  ALGO:  'BINANCE:ALGOUSDT',
  FIL:   'BINANCE:FILUSDT',
  XMR:   'BINANCE:XMRUSDT',
  AAVE:  'BINANCE:AAVEUSDT',
  MKR:   'BINANCE:MKRUSDT',
  CRV:   'BINANCE:CRVUSDT',
  LDO:   'BINANCE:LDOUSDT',
  DYDX:  'BINANCE:DYDXUSDT',
  INJ:   'BINANCE:INJUSDT',
  STX:   'BINANCE:STXUSDT',
  TIA:   'BINANCE:TIAUSDT',
  WIF:   'BINANCE:WIFUSDT',
  PEPE:  'BINANCE:PEPEUSDT',
  BONK:  'BINANCE:BONKUSDT',
  FLOKI: 'BINANCE:FLOKIUSDT',
  TAO:   'BINANCE:TAOUSDT',
  KAS:   'BINANCE:KASUSDT',
  PENDLE:'BINANCE:PENDLEUSDT',
  RNDR:  'BINANCE:RNDRUSDT',
  FET:   'BINANCE:FETUSDT',
  WLD:   'BINANCE:WLDUSDT',
  JUP:   'BINANCE:JUPUSDT',
  JTO:   'BINANCE:JTOUSDT',
  PYTH:  'BINANCE:PYTHUSDT',
  AR:    'BINANCE:ARUSDT',
  GALA:  'BINANCE:GALAUSDT',
  AXS:   'BINANCE:AXSUSDT',
  SAND:  'BINANCE:SANDUSDT',
  MANA:  'BINANCE:MANAUSDT',
  CAKE:  'BINANCE:CAKEUSDT',
  '1INCH':'BINANCE:1INCHUSDT',
  LRC:   'BINANCE:LRCUSDT',
  BAT:   'BINANCE:BATUSDT',
  CHZ:   'BINANCE:CHZUSDT',
  ZIL:   'BINANCE:ZILUSDT',
  ENJ:   'BINANCE:ENJUSDT',
  VET:   'BINANCE:VETUSDT',
  THETA: 'BINANCE:THETAUSDT',
  XTZ:   'BINANCE:XTZUSDT',
  NEO:   'BINANCE:NEOUSDT',
  QTUM:  'BINANCE:QTUMUSDT',
  ICX:   'BINANCE:ICXUSDT',
  EGLD:  'BINANCE:EGLDUSDT',
  ICP:   'BINANCE:ICPUSDT',
  ETC:   'BINANCE:ETCUSDT',
  XLM:   'BINANCE:XLMUSDT',
  TRX:   'BINANCE:TRXUSDT',
  SNX:   'BINANCE:SNXUSDT',
  COMP:  'BINANCE:COMPUSDT',
  YFI:   'BINANCE:YFIUSDT',
  BAL:   'BINANCE:BALUSDT',
  OKB:   'BINANCE:OKBUSDT',
  STORJ: 'BINANCE:STORJUSDT',
  NMR:   'BINANCE:NMRUSDT',
  OCEAN: 'BINANCE:OCEANUSDT',
  ACH:   'BINANCE:ARUSDT',
};

const getTVSymbol = (symbol) => TV_SYMBOL_MAP[symbol] || `BINANCE:${symbol}USDT`;

function TradingViewChart({ symbol = 'BTC', coinColor = '#3b82f6', coinName = 'Bitcoin' }) {
  const containerRef = useRef(null);
  const widgetRef = useRef(null);

  useEffect(() => {
    const containerId = `tv_chart_${symbol.toLowerCase()}_${Math.random().toString(36).substring(7)}`;
    if (containerRef.current) {
      containerRef.current.id = containerId;
    }

    const script = document.createElement('script');
    script.src = 'https://s3.tradingview.com/tv.js';
    script.type = 'text/javascript';
    script.async = true;
    script.onload = () => {
      if (window.TradingView && document.getElementById(containerId)) {
        widgetRef.current = new window.TradingView.widget({
          autosize: true,
          symbol: getTVSymbol(symbol),
          interval: 'D',
          timezone: 'Etc/UTC',
          theme: 'dark',
          style: '1',
          locale: 'en',
          toolbar_bg: '#0d1526',
          enable_publishing: false,
          allow_symbol_change: true,
          container_id: containerId,
          // Explicitly setting background to avoid white screen
          overrides: {
            "paneProperties.background": "#04070d",
            "paneProperties.backgroundType": "solid"
          }
        });
      }
    };
    document.head.appendChild(script);

    return () => {
      if (script.parentNode) {
        script.parentNode.removeChild(script);
      }
      if (containerRef.current) {
        containerRef.current.innerHTML = '';
      }
    };
  }, [symbol]);

  return (
    <div style={{
      width: '100%',
      height: '100%',
      minHeight: '400px', // Ensure it has some initial height
      background: '#04070d',
      position: 'relative',
      display: 'flex',
      flexDirection: 'column'
    }}>
      <div 
        ref={containerRef} 
        style={{ 
          flex: 1, 
          width: '100%', 
          height: '100%',
          overflow: 'hidden' 
        }} 
      />
    </div>
  );
}

export default memo(TradingViewChart);
